import re as _re

_SGR = _re.compile(r"\x1b\[([0-9;]*)m")


def grid(capE):
    """Parse a tmux -e capture into list of rows; each row = list of (char, sgr_state_string)."""
    rows = []
    for line in capE.split("\n"):
        cur = []      # active sgr params in order
        out = []
        i = 0
        while i < len(line):
            m = _SGR.match(line, i)
            if m:
                p = m.group(1)
                for tok in p.split(";") if p else ["0"]:
                    pass
                # crude state: maintain fg/bg/attr strings
                cur = _apply(cur, p)
                i = m.end()
                continue
            out.append((line[i], ";".join(cur)))
            i += 1
        rows.append(out)
    return rows


def _apply(cur, p):
    # cur is list of tokens like 'fg=...','bg=...','a=1'
    toks = p.split(";") if p else ["0"]
    d = dict(t.split("=", 1) for t in cur) if cur else {}
    i = 0
    while i < len(toks):
        t = toks[i]
        if t == "" or t == "0":
            d = {}
        elif t in ("1", "2", "3", "4", "5", "7", "9"):
            d["a" + t] = "1"
        elif t in ("22", "23", "24", "27", "29"):
            d.pop("a" + str(int(t) - 20), None)
            if t == "22":
                d.pop("a1", None); d.pop("a2", None)
        elif t == "38" and i + 1 < len(toks) and toks[i + 1] == "5":
            d["fg"] = "5:" + toks[i + 2]; i += 2
        elif t == "38" and i + 1 < len(toks) and toks[i + 1] == "2":
            d["fg"] = "2:" + ",".join(toks[i + 2:i + 5]); i += 4
        elif t == "48" and i + 1 < len(toks) and toks[i + 1] == "5":
            d["bg"] = "5:" + toks[i + 2]; i += 2
        elif t == "48" and i + 1 < len(toks) and toks[i + 1] == "2":
            d["bg"] = "2:" + ",".join(toks[i + 2:i + 5]); i += 4
        elif t == "39":
            d.pop("fg", None)
        elif t == "49":
            d.pop("bg", None)
        elif t.isdigit() and 30 <= int(t) <= 37:
            d["fg"] = "b:" + t
        elif t.isdigit() and 40 <= int(t) <= 47:
            d["bg"] = "b:" + t
        elif t.isdigit() and 90 <= int(t) <= 97:
            d["fg"] = "b:" + t
        elif t.isdigit() and 100 <= int(t) <= 107:
            d["bg"] = "b:" + t
        i += 1
    return [f"{k}={v}" for k, v in sorted(d.items())]


def cells_with_bg(capE):
    """Return list of (row, col, char, style) for cells that have a bg set."""
    out = []
    for r, row in enumerate(grid(capE)):
        for c, (ch, st) in enumerate(row):
            if "bg=" in st:
                out.append((r, c, ch, st))
    return out


def cursorcell(capE, mincol=30):
    """Cursor = the bg-highlighted cell inside the content pane (col>=mincol)."""
    cs = [x for x in cells_with_bg(capE) if x[1] >= mincol]
    return cs
